      'อ่านค่าจากจอดิจิทัล (ย่านอัตโนมัติ) และจากสเกลของมิเตอร์แบบเข็ม (เลือกย่านเอง)',
      'อธิบายผลการโหลดของมิเตอร์ (loading effect) จากความต้านทานขาเข้า 10 MΩ เทียบกับ 20 kΩ/V',
